window.BANK=window.BANK||{};window.BANK["8612"]={"n":"第二章 新民主主义革命理论","qs":[{"i":"171345","t":"单选","q":"近代中国的社会性质和主要矛盾，决定了中国革命的性质是","o":{"A":"A.无产阶级民主革命","B":"B.新民主主义革命","C":"C.资产阶级民主革命","D":"D.无产阶级社会主义革命"},"a":"C","j":"识记点A.无产阶级民主革命——非考点。B.新民主主义革命——是中国资产阶级民主革命的一个时期，是新式的特殊的资产阶级民主主义的革命。C.资产阶级民主革命——是近代中国革命的性质，是本题正确答案。D.无产阶级社会主义革命——是1949—1956年所进行的革命。","k":"","kid":"","r":10603,"tot":17363},{"i":"171346","t":"单选","q":"毛泽东将新民主主义革命总路线的内容完整地表述为“无产阶级领导的，人民大众的，反对帝国主义、封建主义和官僚资本主义的革命”的文件是","o":{"A":"A.1938年的《论新阶段》","B":"B.1939年的《中国革命和中国共产党》","C":"C.1940年的《新民主主义论》","D":"D.1948年的《在晋绥干部会议上的讲话》"},"a":"D","j":"识记点A.1938年的《论新阶段》—首次提出了“马克思主义的中国化”的命题。B.1939年的《中国革命和中国共产党》——第一次提出了“新民主主义的革命”的科学概念。C.1940年的《新民主主义论》——阐述了新民主主义的政治、经济和文化。D.1948年的《在晋绥干部会议上的讲话》—完整地表述了新民主主义革命总路线的内容，是本题正确答案。","k":"","kid":"","r":9173,"tot":16397},{"i":"171348","t":"单选","q":"帝国主义统治中国和封建军阀实行专制统治的社会基础是","o":{"A":"A.封建土地所有制","B":"B.官僚资产阶级","C":"C.封建地主阶级","D":"D.封建思想的束缚"},"a":"C","j":"识记点A.封建土地所有制—是封建主义的经济基础。B.官僚资产阶级——是依靠帝国主义、勾结封建势力、利用国家政权力量而发展起来的买办的、封建的阶级。C.封建地主阶级——是帝国主义统治中国和封建军阀实行专制统治的社会基础，是本题正确答案。D.封建思想的束缚——非考点。","k":"","kid":"","r":9107,"tot":16025},{"i":"171349","t":"单选","q":"新民主主义革命总路线反映了中国革命的基本规律，指明了中国革命的对象、动力、领导力量、性质和前途。毛泽东在《新民主主义论》中指出，中国革命的基本问题是","o":{"A":"A.政权问题","B":"B.农民问题","C":"C.无产阶级的领导权","D":"D.土地革命"},"a":"B","j":"识记点A.政权问题——是革命的根本问题。B.农民问题——是中国革命的基本问题，是本题正确答案。C.无产阶级的领导权——是中国革命的中心问题，也是新民主主义革命理论的核心问题。D.土地革命——是中国革命的基本内容。","k":"","kid":"","r":9661,"tot":15499},{"i":"171352","t":"单选","q":"毛泽东曾指出，新民主主义共和国，一方面和旧形式的、欧美式的资本主义的共和国相区别；另一方面，也和苏联式的社会主义的共和国相区别。我们的新民主主义国家的国体是","o":{"A":"A.无产阶级专政","B":"B.各革命阶级联合专政","C":"C.资产阶级专政","D":"D.工农联合专政"},"a":"B","j":"识记点A、C、D选项的说法——非考点。B.各革命阶级联合专政——是新民主主义国家的国体，是无产阶级领导的以工农联盟为基础，包括小资产阶级、民族资产阶级和其他反帝反封建的人们在内的各革命阶级的联合专政，是本题正确答案。","k":"","kid":"","r":10435,"tot":14925},{"i":"171354","t":"单选","q":"新民主主义文化是民族的，就其内容说是","o":{"A":"A.反对一切封建思想和迷信思想","B":"B.具有鲜明的民族风格、民族形式和民族特色，要有中国作风和中国气派","C":"C.反对帝国主义压迫，主张中华民族的尊严和独立","D":"D.要以人民群众的实践作为创作的源泉"},"a":"C","j":"识记点A.反对一切封建思想和迷信思想——是新民主主义文化“科学的”内涵。B.具有鲜明的民族风格、民族形式和民族特色，要有中国作风和中国气派——是新民主主义文化“民族的”内涵，但这是就其形式说的，而非内容。C.反对帝国主义压迫，主张中华民族的尊严和独立——是新民主主义文化“民族的”内涵，且是就其内容说的，是本题正确答案。D.要以人民群众的实践作为创作的源泉——是新民主主义文化“大众的”内涵。","k":"","kid":"","r":8526,"tot":15004},{"i":"171355","t":"单选","q":"1938年11月，毛泽东在党的六届六中全会上明确指出：“共产党的任务，基本地不是经过长期合法斗争以进入起义和战争，也不是先占城市后取乡村，而是走相反的道路。”从此把经过长期武装斗争，先占乡村，后取城市，最后夺取全国胜利，作为革命道路确立下来。毛泽东提出该观点的著作是","o":{"A":"A.《战争和战略问题》","B":"B.《中国革命和中国共产党》","C":"C.《在晋绥干部会议上的讲话》","D":"D.《论新阶段》"},"a":"A","j":"<p>识记点A.《战争和战略问题》&mdash;&mdash;是确立革命道路的著作，是本题正确答案。B.《中国革命和中国共产党》&mdash;&mdash;是第一次提出&ldquo;新民主主义的革命&rdquo;科学概念的著作。C.《在晋绥干部会议上的讲话》&mdash;&mdash;是完整表述新民主主义革命总路线的著作。D.《论新阶段》&mdash;&mdash;是首次明确提出&ldquo;马克思主义的中国化&rdquo;重大命题的政治报告。</p>","k":"","kid":"","r":7862,"tot":14998},{"i":"171356","t":"单选","q":"中国革命之所以能走农村包围城市、武装夺取政权的道路，是由中国的特殊国情决定的。其中，农村革命根据地的创立、巩固和发展的坚强后盾是","o":{"A":"A.广大农民的支持和参加","B":"B.党的领导的有力量及其政策的不错误","C":"C.反动统治阶级的多重压迫和剥削","D":"D.相当力量正式红军的存在"},"a":"D","j":"识记点A.广大农民的支持和参加——是一种有力的客观条件，但不是坚强后盾。B.党的领导的有力量及其政策的不错误——为农村革命根据地建设和发展提供了重要的主观条件。C.反动统治阶级的多重压迫和剥削——是广大农民支持和参加农村革命根据地建设和发展的原因，是一种客观条件。D.相当力量正式红军的存在——为农村革命根据地的创立、巩固和发展提供了坚强后盾，是本题正确答案。","k":"","kid":"","r":8584,"tot":14282},{"i":"171358","t":"单选","q":"加强党的组织建设，根本的是","o":{"A":"A.贯彻民主集中制的原则","B":"B.维护中央权威和统一领导","C":"C.联系党的政治路线加强党的建设","D":"D.勇于自我革命"},"a":"A","j":"<p>识记点A.贯彻民主集中制的原则&mdash;&mdash;是加强党的组织建设的根本，是本题正确答案。B.维护中央权威和统一领导&mdash;&mdash;是&ldquo;两个维护&rdquo;之一，是马克思主义执政党的重大建党原则。C.联系党的政治路线加强党的建设&mdash;&mdash;是加强党的建设的经验之一。D.勇于自我革命&mdash;&mdash;是中国共产党区别于其他政党的最显著的标志。</p>","k":"","kid":"","r":6224,"tot":14922},{"i":"171360","t":"单选","q":"中国革命的中心问题是","o":{"A":"A.农民土地问题","B":"B.统一战线问题","C":"C.武装斗争问题","D":"D.领导权问题"},"a":"D","j":"<p><span style=\"color: #000000;\"><strong><span style=\"background-color: #bfedd2;\">出处：肖老师精讲精练P107考点6-4-1</span></strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>领导权的重要性</strong>:无产阶级的领导权是中国革命的<strong>中心问题</strong>，也是新民主主义革命理论的<strong>核心问题</strong>。区别新、旧两种不同范畴的民主主义革命，<strong>根本的标志是革命的领导权掌握在无产阶级手中还是掌握在资产阶级手中。</strong></span></p>\n<p>点拨：关于&ldquo;中心问题&rdquo;的提法：①无产阶级的领导权是中国革命的中心问题。②在中国民主革命中，无产阶级领导权的中心问题是农民问题。③毛泽东在《国民革命与农民运动》中还提到&ldquo;农民问题乃国民革命的中心问题&rdquo;。</p>\n<p>关于首要问题、中心问题、核心问题、基本问题、主要内容、实质等提法的总结，见《2027考研政治知识点精讲精练》第108页表格。</p>\n<p><img src=\"data:image/png;base64,\" alt=\"\" /></p>","k":"考点9：新民主主义革命总路线的内容","kid":"208","r":9975,"tot":13949},{"i":"171361","t":"单选","q":"新民主主义革命时期，党内犯“左”倾错误的人提出“毕其功于一役”的主张，搞所谓的“无间断”革命，这种错误倾向实质上是","o":{"A":"A.混淆了新民主主义革命和社会主义革命的界限","B":"B.割裂了新民主主义革命和社会主义革命的联系","C":"C.混淆了新民主主义革命和资产阶级革命的界限","D":"D.割裂了新民主主义革命和资产阶级革命的联系"},"a":"A","j":"<p><span style=\"color: #000000;\"><strong><span style=\"background-color: #bfedd2;\">出处：肖老师精讲精练P106考点5-3-表格</span></strong></span></p>\n<p><img src=\"https://cangdun.oss-cn-beijing.aliyuncs.com/cdky/cdkyzz/202607/30/26F58FB543D372CE6CB4C33DB927F201.blob\" alt=\"\" /></p>\n<p><span style=\"color: #000000;\"><strong><span style=\"background-color: #bfedd2;\">出处：肖老师精讲精练P108考点6-5-拓展与点拨</span></strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">1在党的历史上，&ldquo;左&rdquo;倾教条主义的&ldquo;一次革命论&rdquo;(如&ldquo;无间断&rdquo;革命论)的错误在于，只看到了民主革命与社会主义革命的联系，而<strong>混淆了民主革命和社会主义革命的区别</strong>，在反帝反封建的同时，也反对民族资产阶级，<strong>否定了中国革命的阶段性。</strong>而右的&ldquo;二次革命论&rdquo;的错误在于，只看到了民主革命和社会主义革命的区别，而<strong>没有看到两个革命阶段的联系，放弃了党对民主革命的领导权。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">2不要把&ldquo;左&rdquo;倾教条主义的&ldquo;无间断&rdquo;革命论与马克思主义的&ldquo;不断革命论&rdquo;相混淆。</span></p>\n<p>点拨：此处涉及两个错误理论：&ldquo;一次革命论&rdquo;和&ldquo;二次革命论&rdquo;。&ldquo;一次革命论&rdquo;(如&ldquo;毕其功于一役&rdquo;)只看到了民主革命与社会主义革命的联系，混淆了民主革命与社会主义革命的区别；&ldquo;二次革命论&rdquo;只看到了民主革命与社会主义革命的区别，割裂了两个革命阶段的联系。</p>","k":"考点9：新民主主义革命总路线的内容","kid":"208","r":9501,"tot":13707},{"i":"171363","t":"单选","q":"新民主主义革命的主要内容是","o":{"A":"A.从根本上推翻反动腐朽的政治上层建筑，变革阻碍生产力发展的生产关系","B":"B.没收官僚资产阶级的垄断资本归新民主主义国家所有","C":"C.没收封建地主阶级的土地归农民所有","D":"D.推翻帝国主义、封建主义和官僚资本主义的统治"},"a":"C","j":"<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P109考点7-2</span></strong></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>经济纲领</strong>:没收封建地主阶级的土地归农民所有(新民主主义革命的主要内容),没收官僚资产阶级的垄断资本归新民主主义的国家所有(双重性质)，保护民族工商业(由中国落后的生产力和新民主主义革命性质所决定的极具特色的一项内容)。</span></p>\n<p><strong>简析：</strong>没收封建地主阶级的土地归农民所有，是新民主主义经济纲领的三项内容之一，是新民主主义革命的主要内容。C正确。推翻帝国主义、封建主义和官僚资本主义的统治，从根本上推翻反动腐朽的政治上层建筑，变革阻碍生产力发展的生产关系，是近代中国革命的根本任务的内容；没收官僚资本归新民主主义国家所有，也是新民主主义经济纲领的三项内容之一，但不是新民主主义革命的主要内容。A、B、D错误。点拨没收封建地主阶级的土地归农民所有，是新民主主义革命的主要内容。没收官僚资本归新民主主义国家所有，是新民主主义革命的题中应有之义。保护民族工商业，是新民主主义经济纲领中极具特色的一项内容。</p>","k":"考点9：新民主主义革命总路线的内容","kid":"208","r":6239,"tot":14194},{"i":"171364","t":"单选","q":"在半殖民地半封建的中国，地主占有土地、将土地出租给农民，通过收取地租来剥削农民，土地制度极不合理。因此，要改变中国贫穷落后的面貌，必须进行土地革命。土地改革的主要和直接任务，就是","o":{"A":"A.限制富农剥削，发展农村生产力","B":"B.没收地主土地归国家所有，分配给农民使用","C":"C.把农民组织起来，开展互助合作","D":"D.满足贫雇农群众的要求"},"a":"D","j":"<p><strong><span style=\"background-color: #bfedd2; color: #000000;\">出处：肖老师精讲精练P109考点7-拓展与点拨3</span></strong></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">土地改革的主要和直接任务，就是满足贫雇农群众的要求。</span></p>\n<p><strong>简析：</strong>党在民主革命时期，逐步认识到土地革命的极端重要性，形成了土地革命路线，这就是依靠贫雇农，团结中农，有步骤、有分别地消灭封建剥削制度，发展农业生产。土地改革所依靠的基本力量，只能和必须是贫农。这个贫农阶层，和雇农在一起，占了当时中国农村人口的70%左右。土地改革的主要和直接任务，就是满足贫雇农群众的要求。D正确。土地改革是没收地主土地分配给农民使用，把土地变为农民的私产，归农民所有，归农民使用。B错误。把农民组织起来，开展互助合作，是土地改革完成、农民分到土地以后的事情，而不是土地改革的主要和直接任务。C错误。土地改革当然也不是限制富农剥削的问题，而是废除封建地主土地所有制的问题。A错误。</p>","k":"考点9：新民主主义革命总路线的内容","kid":"208","r":6794,"tot":14044},{"i":"171367","t":"多选","q":"无产阶级及其政党对中国革命的领导权不是自然而然得来的，而是在与资产阶级争夺领导权的斗争中实现的。毛泽东指出，无产阶级及其政党要实现对同盟者的领导必须具备的条件有","o":{"A":"A.率领同盟者向着共同的敌人作坚决斗争并取得胜利","B":"B.坚持发展进步势力、争取中间势力、孤立顽固势力的策略方针","C":"C.对同盟者给以物质利益，至少不损害其利益，同时给以政治教育","D":"D.对同盟者采取有理、有利、有节的策略原则"},"a":"AC","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P108考点6-4-3</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>决定无产阶级领导权的因素：是由历史和中国无产阶级的特点决定的。</strong>无产阶级及其政党的领导是中国革命取得胜利的<strong>根本保证。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>毛泽东指出：&ldquo;领导的阶级和政党，要实现自己对于被领导的阶级、阶层、政党和人民团体的领导，必须具备两个条件：(甲)率领被领导者(同盟者)向着共同敌人作坚决的斗争，并取得胜利；(乙)对被领导者给以物质福利，至少不损害其利益，同时对被领导者给以政治教育。没有这两个条件或两个条件缺一，就不能实现领导。&rdquo;A、C是毛泽东提出的无产阶级及其政党要实现对同盟者的领导必须具备的两个条件，是正确选项。B是抗日战争时期中共巩固和扩大抗日民族统一战线的策略方针，D是抗日战争时期中共对顽固派斗争的策略，不符合题意，不选。</p>","k":"考点9：新民主主义革命总路线的内容","kid":"208","r":5681,"tot":13530},{"i":"171368","t":"多选","q":"关于新民主主义政治纲领规定的新民主主义国家，以下说法正确的有","o":{"A":"A.国体是各革命阶级联合专政","B":"B.政体是实行民主集中制的人民代表大会制度","C":"C.新民主主义共和国是一定历史时期的国家形式，是过渡的形式","D":"D.人民当家作主是新民主主义国家制度的核心内容和基本准则"},"a":"ABCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P109考点7-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>政治纲领：</strong>推翻帝国主义和封建主义的统治，建立一个无产阶级领导的、以工农联盟为基础的、各革命阶级联合专政的新民主主义的共和国。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>新民主主义国家的国体是无产阶级领导的以工农联盟为基础，包括小资产阶级、民族资产阶级和其他反帝反封建的人们在内的各革命阶级的联合专政。与新民主主义国体相适应的政体，是实行民主集中制的人民代表大会制度。新民主主义国家的国体决定了人民当家作主，由人民行使管理国家的一切权力，这是新民主主义国家制度的核心内容和基本准则，而人民代表大会制度能够最直接、最全面地体现这一核心内容和准则。A、B、D正确。</p>\n<p>新民主主义共和国是一定历史时期的国家形式，是过渡的形式，既不同于欧美式的资产阶级专政的共和国，又和苏联式的无产阶级专政的社会主义共和国相区别。C正确。</p>","k":"考点9：新民主主义革命总路线的内容","kid":"208","r":5753,"tot":13218},{"i":"171369","t":"多选","q":"1948年，毛泽东在《在晋绥干部会议上的讲话》中，在新民主主义革命总路线的革命对象中增加了“官僚资本主义”。把官僚资本主义作为民主革命的对象，是因为官僚资本主义","o":{"A":"A.是资本主义，党作为中国无产阶级的先锋队必须带领人民消灭资本主义剥削制度","B":"B.背靠帝国主义，充当帝国主义的买办，是买办的、封建的国家垄断资本主义","C":"C.同大地主、大资产阶级的反革命国家政权密切结合着，成为国民党统治的经济基础","D":"D.严重束缚了中国社会生产力的发展，对中国社会进步起着严重的阻碍作用"},"a":"BCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P109考点7拓展与点拨1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>拓展与点拨</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">①反对官僚资本主义并非因为它是资本主义，而是因为这种资本主义同外国帝国主义、本国地主阶级和旧式富农密切地结合着，<strong>是一种买办的封建的国家垄断资本主义</strong>；是因为这种资本主义是同大地主大资产阶级的反革命国家政权密切结合着，<strong>成为国民党统治的经济基础；是因为这种资本主义对中国的经济发展和社会进步起着严重的阻碍作用</strong>。没收官僚资本，<strong>包含着新民主主义革命和社会主义革命的双重性质。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>没收官僚资本归新民主主义国家所有，是新民主主义革命的题中应有之义。反对官僚资本主义并非因为它是资本主义，而是因为这种资本主义同外国帝国主义、本国地主阶级和旧式富农密切地结合着，是一种买办的、封建的国家垄断资本主义；是因为这种资本主义是同大地主、大资产阶级的反革命国家政权密切结合着，成为国民党统治的经济基础；是因为这种资本主义对中国的经济发展和社会进步起着严重的阻碍作用。官僚资本主义对广大劳动人民的残酷剥削和对民族工商业的巧取豪夺，严重束缚了中国社会生产力的发展。因此也是中国革命的对象。B、C、D正确，A错误。</p>","k":"考点9：新民主主义革命总路线的内容","kid":"208","r":7435,"tot":12699},{"i":"171370","t":"多选","q":"新民主主义革命的对象是帝国主义、封建主义和官僚资本主义，它不是一般地消灭资本主义和资产阶级，“它只推翻帝国主义和汉奸反动派在中国的统治，而不破坏任何尚能参加反帝反封建的资本主义成分”。在新民主主义条件下保护民族工商业，发展资本主义，这是因为","o":{"A":"A.同官僚资产阶级相比，民族资产阶级与帝国主义和封建主义联系较少","B":"B.民族资本主义经济是一种与新生产力相联系的先进的生产方式和经济成分","C":"C.让私人资本主义经济在不能操纵国计民生的范围内获得发展的便利，有益于社会向前发展","D":"D.民族资本家经营的企业在中国社会经济中占主要地位，保护民族工商业有利于社会稳定"},"a":"ABC","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P109考点7拓展与点拨2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">同官僚资产阶级相比，民族资产阶级与帝国主义和封建主义联系较少。民族资本主义经济，<strong>是一种与新生产力相联系的先进的生产方式和经济成分，它对发展现代技术、发展社会生产力具有积极作用。</strong>因此，对民族资本主义工商业必须采取保护政策。</span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>A、B、C正确。民族资本家经营的企业由于原始积累不足，大多数规模小、设备落后，并受到外国资本主义和本国封建主义及官僚买办资产阶级的压迫，发展缓慢，始终未能在中国社会经济中占主要地位。D错误。</p>","k":"考点9：新民主主义革命总路线的内容","kid":"208","r":7670,"tot":12458},{"i":"171371","t":"多选","q":"1938年11月，毛泽东在《战争和战略问题》中明确指出：“共产党的任务，基本地不是经过长期合法斗争以进入起义和战争，也不是先占城市后取乡村，而是走相反的道路。”中国走农村包围城市、武装夺取政权道路的依据是","o":{"A":"A.无产阶级是革命的领导阶级","B":"B.农民占全国人口的绝大多数，是无产阶级可靠的同盟军和革命的主力军","C":"C.当时的中国内无民主制度而受封建主义的压迫，外无民族独立而受帝国主义的压迫","D":"D.在半殖民地半封建的近代中国，封建主义和人民大众的矛盾是各种矛盾中最主要的矛盾"},"a":"BC","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P110考点8-2-1</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">中国革命必须走农村包围城市、武装夺取政权的道路，<strong>是由中国所处的时代特点和具体国情决定的。</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>第一，</strong>在半殖民地半封建的中国社会，<strong>内无民主制度而受封建主义的压迫，外无民族独立</strong><strong>而受帝国主义的压迫。</strong>中国革命的<strong>主要斗争形式只能是武装斗争</strong>，相应的主要组织形式必然是军队。</span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>第二，近代中国是一个农业大国，农民占全国人口的绝大多数，是无产阶级可靠的同盟军和革命的主力军。</strong>无产阶级及其政党必须深入农村，解决农民的土地问题，使革命战争获得广大农民的支持和参加，<strong>才能为最后夺取全国政权奠定基础。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>B、C正确。无产阶级是革命的领导阶级，不是中国走农村包围城市、武装夺取政权道路的依据。俄国十月革命也是无产阶级领导的，但走的却是城市包围农村的道路，A错误。在半殖民地半封建的近代中国，社会矛盾呈现出错综复杂的状况。在诸多社会矛盾中，占支配地位的主要矛盾是帝国主义和中华民族的矛盾、封建主义和人民大众的矛盾，而帝国主义和中华民族的矛盾又是各种矛盾中最主要的矛盾。D错误。</p>","k":"考点11：新民主主义革命的道路","kid":"210","r":4770,"tot":13094},{"i":"171372","t":"多选","q":"近代中国社会的阶级结构是“两头小中间大”,“中间”是指","o":{"A":"A.无产阶级","B":"B.农民阶级","C":"C.民族资产阶级","D":"D.城市小资产阶级"},"a":"BCD","j":"<p>考点拓展题</p>\n<p><strong>简析：</strong>中国社会的阶级结构是&ldquo;两头小中间大&rdquo;,&ldquo;两头&rdquo;的一头是无产阶级，另一头是地主大资产阶级，&ldquo;两头小&rdquo;即占少数；&ldquo;中间&rdquo;是指农民、城市小资产阶级以及其他中间阶级，占多数。B、C、D正确。A是&ldquo;两头&rdquo;中的一头。</p>\n<p><strong>点拨：</strong>在&ldquo;习近平新时代中国特色社会主义思想概论&rdquo;这门课程中也有一个类似的&ldquo;两头小中间大&rdquo;的比喻：在分配问题上，我们要&ldquo;扩大中等收入群体比重，增加低收入群体收入，合理调节高收入，取缔非法收入，形成中间大、两头小的橄榄型分配结构&rdquo;(橄榄型分配结构是一种以中等收入群体为主体、高收入和低收入群体占比均较小的收入分配模式，其核心特征是&ldquo;中间大、两头小&rdquo;,形似橄榄)。</p>","k":"考点12：新民主主义革命的三大法宝","kid":"211","r":6669,"tot":12378},{"i":"171373","t":"多选","q":"开展革命的政治工作是党在新民主主义革命时期建设人民军队的经验之一。人民军队政治工作的基本原则包括","o":{"A":"A.支部建在连上的原则","B":"B.官兵一致的原则","C":"C.军民一致的原则","D":"D.瓦解敌军和优待俘虏的原则"},"a":"BCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P111考点9-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>2.武装斗争(中国革命的特点和优点之一)</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\">建设人民军队，<strong>一要坚持党对军队的绝对领导</strong>，这是建设新型人民军队的<strong>根本原则</strong>，是保持人民军队无产阶级性质和建军宗旨的根本前提，也是毛泽东建军思想的<strong>核心</strong>。<strong>二要建设全心全意为人民服务的人民军队</strong>。全心全意为人民服务是人民军队的唯一宗旨，是建设新型人民军队的<strong>基本前提</strong>，也是人民军队一切行动的<strong>根本准则</strong>和一切工作的<strong>出发点与归宿</strong>。<strong>三要开展革命的政治工作</strong>，实行官兵一致的原则、军民一致的原则(军队要减轻民众的经济负担，宣传、组织和武装民众)、瓦解敌军和优待俘虏的原则。<strong>四要坚持正确的战略战术原则。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>人民军队政治工作的基本原则包括：官兵一致的原则，就是在军队内部建立自觉纪律，实行同甘共苦的生活，官兵待遇平等；军民一致的原则，就是军队要减轻民众的经济负担，宣传、组织和武装民众；瓦解敌军和优待俘虏的原则，就是要削弱敌人、壮大自己。B、C、D正确。&ldquo;支部建在连上&rdquo;属于坚持党对军队的绝对领导的内容，A错误。</p>","k":"考点12：新民主主义革命的三大法宝","kid":"211","r":6216,"tot":12354},{"i":"171374","t":"多选","q":"毛泽东在中共七大上总结的中国共产党区别于其他任何政党的显著标志有","o":{"A":"A.谦虚、谨慎、不骄、不躁的作风","B":"B.理论和实践相结合的作风","C":"C.自我批评的作风","D":"D.和人民群众紧密地联系在一起的作风"},"a":"BCD","j":"<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>出处：肖老师精讲精练P111考点9-3-2</strong></span></p>\n<p><span style=\"background-color: #bfedd2; color: #000000;\"><strong>经验(也是党的建设的内容):第一，必须把思想建设始终放在党的建设的首位。关键是要</strong>以无产阶级思想克服和改造各种非无产阶级思想。<strong>第二，必须在任何时候都重视党的组织建设。根本的是要</strong>贯彻民主集中制这一根本组织原则。<strong>第三，必须重视党的作风建设。</strong>党在领导新民主主义革命的过程中，把党的建设作为一项&ldquo;伟大的工程&rdquo;,逐步形成理论联系实际、密切联系群众、批评与自我批评相结合的<strong>三大优良作风</strong>，这是中国共产党区别于其他任何政党的<strong>显著标志。第四，必须联系党的政治路线加强党的建设。</strong></span></p>\n<p>&nbsp;</p>\n<p><strong>简析：</strong>B、C、D正确。A是在党的七届二中全会上提出的，不符合题意。点拨中共七大是在1945年召开的。中共七届二中全会是在1949年3月(&ldquo;进京赶考&rdquo;前夕)召开的。在中共七届二中全会上，毛泽东告诫全党，夺取全国胜利，这只是万里长征走完了第一步，中国的革命是伟大的，但革命以后的路更长，工作更伟大、更艰苦。据此，他提出了&ldquo;两个务必&rdquo;的思想，即&ldquo;务必使同志们继续地保持谦虚、谨慎、不骄、不躁的作风，务必使同志们继续地保持艰苦奋斗的作风&rdquo;。</p>","k":"考点12：新民主主义革命的三大法宝","kid":"211","r":7835,"tot":11983},{"i":"171375","t":"多选","q":"无产阶级的领导权问题是","o":{"A":"A.新民主主义革命理论的核心问题","B":"B.中国资产阶级民主革命的中心问题","C":"C.中国革命的基本问题","D":"D.中国革命的中心问题"},"a":"AD","j":"识记点A、D选项的说法——是无产阶级的领导权问题，是本题正确答案。B.中国资产阶级民主革命的中心问题——是土地革命。C.中国革命的基本问题——是农民问题。","k":"","kid":"","r":6691,"tot":12320},{"i":"171377","t":"多选","q":"1925年，毛泽东在《中国社会各阶级的分析》中指出，谁是我们的敌人?谁是我们的朋友?这个问题是革命的首要问题。因此，党在不同时期的革命的主要对象有","o":{"A":"A.在国共合作的大革命时期，革命的主要对象是帝国主义支持下的国民党新军阀","B":"B.在土地革命战争时期，革命的主要对象是北洋军阀","C":"C.在抗日战争时期，革命的主要对象是日本帝国主义","D":"D.在解放战争时期，革命的主要对象是美帝国主义支持下的国民党反动派"},"a":"CD","j":"识记点A选项的说法——是错误说法，大革命时期，革命的主要对象是帝国主义支持下的北洋军阀。B选项的说法——是错误说法，土地革命战争时期，革命的主要对象是国民党新军阀。C、D选项的说法——是正确说法，是本题正确答案。","k":"","kid":"","r":7085,"tot":12067},{"i":"171378","t":"多选","q":"新民主主义文化，就是无产阶级领导的人民大众的反帝反封建的文化，即民族的科学的大众的文化。其中，“科学的”文化的内涵包括","o":{"A":"A.要尊重中国的历史，反对民族虚无主义","B":"B.反对一切封建思想和迷信思想，主张实事求是、客观真理及理论和实践的一致性","C":"C.剔除封建性的糟粕，吸收民主性的精华","D":"D.要以人民群众的实践作为创作的源泉，坚持为人民大众服务的方向"},"a":"ABC","j":"<p>识记点A、B、C选项的说法&mdash;&mdash;是&ldquo;科学的&rdquo;文化的内涵，是本题正确答案。D选项的说法&mdash;&mdash;是&ldquo;大众的&rdquo;文化的内涵。</p>","k":"","kid":"","r":5935,"tot":12335},{"i":"171380","t":"多选","q":"党的六届六中全会确立了经过长期武装斗争，先占乡村，后取城市，最后夺取全国胜利的革命道路。新民主主义革命道路形成的必然性包括","o":{"A":"A.社会政治经济发展极端不平衡，四分五裂，军阀割据，存在不少的统治薄弱环节","B":"B.在半殖民地半封建的中国社会，内无民主制度，外无民族独立","C":"C.近代中国农民占全国人口的绝大多数，是无产阶级可靠的同盟军和革命的主力军","D":"D.党的领导的有力量及其政策的不错误"},"a":"BC","j":"<p>识记点A、D选项的说法&mdash;&mdash;是新民主主义革命道路形成的可能性，而非必然性。B、C选项的说法&mdash;&mdash;是新民主主义革命道路形成的必然性，是本题正确答案。</p>","k":"","kid":"","r":4181,"tot":12652},{"i":"171383","t":"多选","q":"党成立以来，多次与不同阶级包括资产阶级，建立了统一战线。中国革命必须建立最广泛的统一战线，是因为","o":{"A":"A.半殖民地半封建的中国社会，诸多矛盾交织在一起","B":"B.中国半殖民地半封建社会的阶级状况是“两头小中间大”","C":"C.中国革命的长期性、残酷性及发展的不平衡性","D":"D.全国革命形势的继续向前发展，为在农村建设革命根据地提供了客观条件"},"a":"BC","j":"<p>识记点A选项的说法&mdash;&mdash;是建立统一战线的可能性。B、C选项的说法&mdash;&mdash;是建立统一战线的必要性，是本题正确答案。D选项的说法&mdash;&mdash;是中国走农村包围城市革命道路的可能性。</p>","k":"","kid":"","r":3416,"tot":12910},{"i":"171385","t":"多选","q":"官僚资本主义对广大劳动人民的残酷剥削和对民族工商业的巧取豪夺，严重束缚了中国社会生产力的发展，因此也是中国革命的对象。官僚资本主义()","o":{"A":"A.是中国社会进步和发展的最大障碍","B":"B.依靠帝国主义、勾结封建势力","C":"C.是买办的、封建的国家垄断资本主义","D":"D.是帝国主义统治中国和封建军阀实行专制统治的社会基础"},"a":"BC","j":"<p>官僚资本主义对广大劳动人民的残酷剥削和对民族工商业的巧取豪夺，严重束缚了中国社会生产力的发展，因此也是中国革命的对象。<span style=\"color: #e03e2d;\">|</span><strong>官僚资本主义</strong>()</p>\n<p>A.是中国社会进步和发展的<strong>最大障碍</strong><span style=\"background-color: #f8cac6; color: #000000;\">这是帝国主义</span></p>\n<p>B.依靠帝国主义、勾结封建势力&radic;</p>\n<p>C.是买办的、封建的国家垄断资本主义&radic;</p>\n<p>D.是帝国主义统治中国和封建军阀实行专制统治的<strong>社会基础</strong><span style=\"background-color: #f8cac6; color: #000000;\">这是封建地主阶级</span></p>\n<p>【答案】BC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">官僚资本主义依靠帝国主义、勾结封建势力，是买办的、封建的国家垄断资本主义。</span></p>","k":"考点9：新民主主义革命总路线的内容","kid":"208","r":5533,"tot":12265},{"i":"171387","t":"多选","q":"毛泽东同志在《青年运动的方向》一文中指出：革命的动力，有无产阶级，有农民阶级，还有其他阶级中一切愿意反帝反封建的人，他们都是反帝反封建的革命力量。下列关于新民主主义革命动力理解正确的是()","o":{"A":"A.工农联盟是中国革命最基本的动力","B":"B.农民阶级是中国革命的主力军","C":"C.贫雇农是无产阶级最可靠的同盟军","D":"D.城市小资产阶级是无产阶级的可靠同盟者"},"a":"BCD","j":"<p>毛泽东同志在《青年运动的方向》一文中指出：革命的动力，有无产阶级，有农民阶级，还有其他阶级中一切愿意反帝反封建的人，他们都是反帝反封建的革命力量。<span style=\"color: #e03e2d;\">|</span>下列关于<span style=\"background-color: #f8cac6; color: #000000;\">新民主主义革命动力</span><strong>理解正确的是</strong>()</p>\n<p>A.<strong>工农联盟</strong>是中国革命<strong>最基本的动力</strong><span style=\"background-color: #f8cac6; color: #000000;\">是无产阶级</span></p>\n<p>B.<strong>农民阶级</strong>是中国革命的<strong>主力军</strong>&radic;</p>\n<p>C.<strong>贫雇农</strong>是无产阶级<strong>最可靠的同盟军</strong>&radic;</p>\n<p>D.<strong>城市小资产阶级</strong>是无产阶级的<strong>可靠同盟者</strong>&radic;</p>\n<p>【答案】BCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">农民阶级是中国革命的主力军，贫雇农是无产阶级最可靠的同盟军，城市小资产阶级是无产阶级的可靠同盟者。</span></p>","k":"考点9：新民主主义革命总路线的内容","kid":"208","r":5188,"tot":12121},{"i":"171389","t":"多选","q":"中国共产党从1921年成立至今，共经历了五次统一战线。在党领导中国人民进行新民主主义革命和社会主义建设的过程中形成、发展和壮大起来的统一战线，在不同的历史时期有着不同的任务、内容以及特点。建立统一战线的必要性是()","o":{"A":"A.中国半殖民地半封建社会的阶级状况","B":"B.中国社会是“两头小中间大”的社会","C":"C.半殖民地半封建的中国社会，诸多矛盾交织在一起","D":"D.中国革命的长期性、残酷性及其发展的不平衡性"},"a":"ABD","j":"<p>中国共产党从1921年成立至今，共经历了五次统一战线。在党领导中国人民进行新民主主义革命和社会主义建设的过程中形成、发展和壮大起来的统一战线，在不同的历史时期有着不同的任务、内容以及特点。<span style=\"background-color: #f8cac6; color: #000000;\">建立统一战线</span>的<strong>必要性</strong>是()</p>\n<p>A.中国半殖民地半封建社会的阶级状况&radic;</p>\n<p>B.中国社会是&ldquo;两头小中间大&rdquo;的社会&radic;</p>\n<p>C.半殖民地半封建的中国社会，诸多矛盾交织在一起<span style=\"background-color: #f8cac6; color: #000000;\">这是可能性</span></p>\n<p>D.中国革命的长期性、残酷性及其发展的不平衡性&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">建立统一战线的必要性在于中国半殖民地半封建社会的阶级状况，中国社会是&ldquo;两头小中间大&rdquo;的社会，中国革命的长期性、残酷性及其发展的不平衡性。</span></p>","k":"考点12：新民主主义革命的三大法宝","kid":"211","r":3939,"tot":12633},{"i":"171393","t":"多选","q":"新民主主义文化，就是无产阶级领导的人民大众的反帝反封建的文化，即民族的科学的大众的文化。其中，科学的文化是要求我们()","o":{"A":"A.反对一切封建思想和迷信思想","B":"B.剔除封建文化中的封建糟粕，吸收其民主精华","C":"C.以历史唯物主义的态度对待古今中外文化","D":"D.具有鲜明的民族风格、民族形式和民族特色"},"a":"ABC","j":"<p>新民主主义文化，就是无产阶级领导的人民大众的反帝反封建的文化，即民族的科学的大众的文化。<span style=\"color: #e03e2d;\">|</span>其中，科学的文化是要求我们()</p>\n<p>A.反对一切封建思想和迷信思想&radic;</p>\n<p>B.剔除封建文化中的封建糟粕，吸收其民主精华&radic;</p>\n<p>C.以历史唯物主义的态度对待古今中外文化&radic;</p>\n<p><span style=\"background-color: #f8cac6; color: #000000;\">ABC即一切反封建、与马克思主义有关</span></p>\n<p>D.具有鲜明的民族风格、民族形式和民族特色<span style=\"background-color: #f8cac6; color: #000000;\">这是民族的文化</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">科学的文化是要求我们反对一切封建思想和迷信思想，剔除封建文化中的封建糟粕，吸收其民主精华，以历史唯物主义的态度对待古今中外文化。即一切反封建、与马克思主义有关。</span></p>","k":"考点10：新民主主义的基本纲领","kid":"209","r":8052,"tot":11438},{"i":"171394","t":"多选","q":"邓小平同志指出：“马克思、列宁从来没有说过农村包围城市，这个原理在当时世界上还是没有的。但是毛泽东同志根据中国的具体条件指明了革命的具体道路。”毛泽东同志找到农村包围城市、武装夺取政权这条道路的根据是()","o":{"A":"A.中国内无民主制度，外无民族独立","B":"B.农民占人口绝大多数，是民主革命的主力军","C":"C.中国革命的敌人长期占据着中心城市，农村是其统治的薄弱环节","D":"D.中国经济政治发展的不平衡"},"a":"ABCD","j":"<p>邓小平同志指出：&ldquo;马克思、列宁从来没有说过农村包围城市，这个原理在当时世界上还是没有的。但是毛泽东同志根据中国的具体条件指明了革命的具体道路。&rdquo;<span style=\"color: #e03e2d;\">||</span>毛泽东同志找到<span style=\"background-color: #f8cac6; color: #000000;\">农村包围城市、武装夺取政权</span>这条道路的<strong>根据是</strong>()</p>\n<p>A.中国内无民主制度，外无民族独立&radic;</p>\n<p>B.农民占人口绝大多数，是民主革命的主力军&radic;</p>\n<p>C.中国革命的敌人长期占据着中心城市，农村是其统治的薄弱环节&radic;</p>\n<p>D.中国经济政治发展的不平衡&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">毛泽东同志找到农村包围城市、武装夺取政权这条道路的根据是中国内无民主制度，外无民族独立；农民占人口绝大多数，是民主革命的主力军；中国革命的敌人长期占据着中心城市，农村是其统治的薄弱环节；中国经济政治发展的不平衡。</span></p>","k":"考点11：新民主主义革命的道路","kid":"210","r":5434,"tot":12105}]};
